"""Explanatory diagrams for the paper (vector PDFs in figures/), regenerated by `make.py diagrams`.

One style for all: the Okabe–Ito colour-blind-safe palette, with hatching or line style as a second
cue so each figure reads in greyscale; thin lines; every element labelled; no decoration.

    a  diag-representations.pdf   a tilted square (2-D) and a tilted cube (3-D): true surface,
                                  staircase voxels, interior cells + clipped boundary pieces
    b  diag-fill-moments.pdf      fill fraction, centroid against cell centre, second moment
    c  diag-cuts.pdf              one cell cut by planes: the clipped piece in each case
    d  diag-closed-form.pdf       one face and one edge as the closed form sees them
    (e, the layered read, is drawn with the octree figures in octree_diagrams.py)

Words as the paper uses them: "exact" is the analytic shape; a clipped piece is exact *to the mesh*.

    python scripts/diagrams.py
"""

from __future__ import annotations

import pathlib
import sys

import matplotlib as mpl
import matplotlib.pyplot as plt
import numpy as np
from matplotlib.patches import Ellipse, FancyArrowPatch, Polygon, Rectangle
from mpl_toolkits.mplot3d.art3d import Poly3DCollection

HERE = pathlib.Path(__file__).resolve().parent
FIG = HERE.parent / "figures"
sys.path.insert(0, str(HERE.parents[2] / "research" / "exact-skin-and-partial-fill"))
import skin_bench  # noqa: E402

# Okabe–Ito
BLUE, ORANGE, GREEN, VERMILION, SKY, YELLOW, PURPLE = (
    "#0072B2", "#E69F00", "#009E73", "#D55E00", "#56B4E9", "#F0E442", "#CC79A7")
INK, INK2, GHOST = "#111111", "#555555", "#bbbbbb"


def style() -> None:
    mpl.rcParams.update({
        "font.family": "serif", "font.size": 8, "axes.linewidth": 0.6, "lines.linewidth": 1.0,
        "hatch.linewidth": 0.5, "savefig.bbox": "tight", "pdf.fonttype": 42,
        "mathtext.fontset": "dejavuserif",
    })


def bare(ax: plt.Axes) -> None:
    ax.set_aspect("equal")
    ax.set_xticks([])
    ax.set_yticks([])
    for s in ax.spines.values():
        s.set_visible(False)


# ------------------------------------------------------------------ 2-D clipping

def clip_poly(poly: np.ndarray, a: np.ndarray, b: np.ndarray) -> np.ndarray:
    """Sutherland–Hodgman: keep the part of `poly` left of the directed line a→b."""
    out = []
    n = len(poly)
    side = lambda p: (b[0] - a[0]) * (p[1] - a[1]) - (b[1] - a[1]) * (p[0] - a[0])  # noqa: E731
    for i in range(n):
        p, q = poly[i], poly[(i + 1) % n]
        sp, sq = side(p), side(q)
        if sp >= 0:
            out.append(p)
        if (sp >= 0) != (sq >= 0):
            t = sp / (sp - sq)
            out.append(p + t * (q - p))
    return np.array(out)


def clip_convex(cell: np.ndarray, body: np.ndarray) -> np.ndarray:
    poly = cell
    for i in range(len(body)):
        if len(poly) == 0:
            break
        poly = clip_poly(poly, body[i], body[(i + 1) % len(body)])
    return poly


def area(poly: np.ndarray) -> float:
    if len(poly) < 3:
        return 0.0
    x, y = poly[:, 0], poly[:, 1]
    return 0.5 * float(np.dot(x, np.roll(y, -1)) - np.dot(y, np.roll(x, -1)))


def centroid(poly: np.ndarray) -> np.ndarray:
    x, y = poly[:, 0], poly[:, 1]
    cr = x * np.roll(y, -1) - np.roll(x, -1) * y
    a = 0.5 * cr.sum()
    return np.array([((x + np.roll(x, -1)) * cr).sum(), ((y + np.roll(y, -1)) * cr).sum()]) / (6 * a)


def second_moment(poly: np.ndarray, c: np.ndarray) -> np.ndarray:
    """∫(x−c)(x−c)ᵀ dA of a polygon, by triangles from c."""
    m = np.zeros((2, 2))
    for i in range(len(poly)):
        p, q = poly[i] - c, poly[(i + 1) % len(poly)] - c
        a = 0.5 * (p[0] * q[1] - p[1] * q[0])
        m += a / 6.0 * (np.outer(p, p) + np.outer(q, q) + 0.5 * (np.outer(p, q) + np.outer(q, p)))
    return m


def rot2(t: float) -> np.ndarray:
    return np.array([[np.cos(t), -np.sin(t)], [np.sin(t), np.cos(t)]])


# ------------------------------------------------------------------ a

def inside_convex(pt: np.ndarray, body: np.ndarray) -> bool:
    """Whether a point is inside an anticlockwise convex polygon."""
    for i in range(len(body)):
        a, b = body[i], body[(i + 1) % len(body)]
        if (b[0] - a[0]) * (pt[1] - a[1]) - (b[1] - a[1]) * (pt[0] - a[0]) < 0:
            return False
    return True


LIGHT = np.array([-0.4, -0.7, 0.6]) / np.linalg.norm([-0.4, -0.7, 0.6])


def shaded(polys: list[np.ndarray] | np.ndarray, color: str, alpha: float = 1.0) -> list:
    """Face colours lit by one light, so solids read as 3-D without edges on every triangle."""
    base = np.array(mpl.colors.to_rgb(color))
    out = []
    for q in polys:
        n = np.cross(q[1] - q[0], q[2] - q[0])
        nn = np.linalg.norm(n)
        k = 0.55 + 0.45 * max(0.0, float(np.dot(n / nn, LIGHT))) if nn > 0 else 0.8
        out.append((*np.clip(base * k + (1 - k) * 0.15, 0, 1), alpha))
    return out


def add_solid(ax, polys, color: str, edge: str | None = None, lw: float = 0.0,
              alpha: float = 1.0) -> None:
    polys = list(polys)
    ax.add_collection3d(Poly3DCollection(polys, facecolors=shaded(polys, color, alpha),
                                         edgecolors=edge if edge else "none", linewidths=lw))


def fig_representations() -> None:
    fig = plt.figure(figsize=(6.8, 4.6))
    body = (np.array([[-1, -1], [1, -1], [1, 1], [-1, 1]]) * 2.15) @ rot2(0.42).T + [0.13, 0.07]
    h = 1.0
    cells = [(i, j) for i in range(-4, 4) for j in range(-4, 4)]
    titles = ["true surface", "plain cubes (staircase)", "interior cubes + clipped pieces"]
    for k in range(3):
        ax = fig.add_subplot(2, 3, k + 1)
        bare(ax)
        for i, j in cells:
            ax.add_patch(Rectangle((i * h, j * h), h, h, fill=False, ec=GHOST, lw=0.4))
        if k == 0:
            ax.add_patch(Polygon(body, fc=SKY, ec=BLUE, lw=1.2))
        else:
            for i, j in cells:
                sq = np.array([[i, j], [i + 1, j], [i + 1, j + 1], [i, j + 1]], float) * h
                piece = clip_convex(sq, body)
                a = area(piece) if len(piece) >= 3 else 0.0
                full = abs(a - h * h) < 1e-9
                if k == 1:
                    if inside_convex((np.array([i, j]) + 0.5) * h, body):
                        ax.add_patch(Rectangle((i * h, j * h), h, h, fc=SKY, ec=BLUE, lw=0.6))
                elif full:
                    ax.add_patch(Rectangle((i * h, j * h), h, h, fc=SKY, ec=BLUE, lw=0.6))
                elif a > 1e-9:
                    ax.add_patch(Polygon(piece, fc=ORANGE, ec=VERMILION, lw=0.6, hatch="////"))
            ax.add_patch(Polygon(body, fill=False, ec=INK, lw=0.8, ls="--"))
        ax.set_xlim(-4.2, 4.2)
        ax.set_ylim(-4.2, 4.2)
        ax.set_title(f"({'abc'[k]}) {titles[k]}", fontsize=8)
    # 3-D row: the benchmark's turned cube on a coarse lattice, clipped by the benchmark's own
    # clipper; (f) shows the lower half, to reveal the interior cubes.
    tris = skin_bench.body("cube")
    quads = turned_cube_quads()
    h3 = 0.2
    off = lat_off()
    lat = skin_bench.lattice(tris, h3, off)
    pn, pd = skin_bench.planes_of(tris)
    lo = np.floor((tris.reshape(-1, 3).min(0) - off) / h3).astype(int)
    hi = np.floor((tris.reshape(-1, 3).max(0) - off) / h3).astype(int)
    g = np.stack(np.meshgrid(*[np.arange(lo[i], hi[i] + 1) for i in range(3)], indexing="ij"),
                 -1).reshape(-1, 3)
    cs = off + (g + 0.5) * h3
    sup = 0.5 * h3 * np.abs(pn).sum(1)
    front = lambda c: (c[..., 0] > 0) & (c[..., 1] < 0) & (c[..., 2] > -0.1)  # noqa: E731
    for k in range(3):
        ax = fig.add_subplot(2, 3, 4 + k, projection="3d")
        ax.set_axis_off()
        ax.set_box_aspect((1, 1, 1))
        ax.view_init(elev=22, azim=-58)
        if k == 0:
            add_solid(ax, quads, SKY, edge=BLUE, lw=0.6)
        elif k == 1:
            keep = cs[np.all(cs @ pn.T - pd <= 0, axis=1)]
            add_solid(ax, skin_bench.cube_quads(keep, h3), SKY, edge=BLUE, lw=0.2)
        else:
            inner = cs[np.all(cs @ pn.T - pd + sup <= 0, axis=1)]
            inner = inner[inner[:, 2] < 0.0]
            pieces = lat["pieces"]
            cen = pieces.mean(axis=1)
            cubes = list(skin_bench.cube_quads(inner, h3))
            low = list(pieces[cen[:, 2] < 0.0])
            # one collection, so matplotlib sorts cubes and pieces together by depth
            ax.add_collection3d(Poly3DCollection(
                cubes + low, facecolors=shaded(cubes, SKY) + shaded(low, ORANGE),
                edgecolors=[BLUE] * len(cubes) + ["none"] * len(low),
                linewidths=[0.2] * len(cubes) + [0.0] * len(low)))
            ax.view_init(elev=40, azim=-58)
        r = 0.7
        ax.set_xlim(-r, r)
        ax.set_ylim(-r, r)
        ax.set_zlim(-r, r)
        ax.set_title(f"({'def'[k]})", fontsize=8, pad=-6)
    fig.text(0.5, 0.03, "blue: the true body, or whole cells; orange (hatched in 2-D): clipped "
             "boundary pieces, exact to the polygon or mesh; dashed: the true surface. "
             "(f) shows the lower half only, cut level with the centre.", ha="center", fontsize=6.8)
    fig.savefig(FIG / "diag-representations.pdf")
    plt.close(fig)


def turned_cube_quads() -> np.ndarray:
    """The benchmark's turned cube as six quads (for drawing without triangle diagonals)."""
    q = skin_bench.cube_quads(np.zeros((1, 3)), 1.0) * 0.8
    return q @ skin_bench.rotation(3).T


def lat_off() -> np.ndarray:
    return np.array([0.05, 0.11, 0.07])


# ------------------------------------------------------------------ b

def fig_fill_moments() -> None:
    fig, axes = plt.subplots(1, 3, figsize=(6.8, 2.4))
    # a surface (line) crossing a row of three cells; the body is below the line
    a, b = np.array([0.0, -0.2]), np.array([3.0, 1.2])

    def cut(i: int) -> np.ndarray:
        sq = np.array([[i, 0], [i + 1, 0], [i + 1, 1], [i, 1]], float)
        return clip_poly(sq, b, a)  # keep the side below the line

    titles = ["(a) fill fraction $f$", "(b) mass at the centroid $\\bar{\\mathbf{c}}$",
              "(c) + second moment $I$"]
    notes = ["shade and number:\nhow full each cell is", "+ cell centre\n\u25cf centroid of the filled part",
             "ellipse: the filled part's\nsecond moment"]
    for k, ax in enumerate(axes):
        bare(ax)
        for i in range(3):
            ax.add_patch(Rectangle((i, 0), 1, 1, fill=False, ec=INK2, lw=0.6))
            piece = cut(i)
            f = area(piece)
            shade = mpl.colors.to_rgba(BLUE, 0.15 + 0.75 * f)
            ax.add_patch(Polygon(piece, fc=shade if k == 0 else mpl.colors.to_rgba(SKY, 0.6),
                                 ec=BLUE, lw=0.6))
            cc = np.array([i + 0.5, 0.5])
            if k == 0:
                ax.text(i + 0.5, 1.07, f"{f:.2f}", ha="center", fontsize=7.5)
            if k >= 1:
                c = centroid(piece)
                ax.plot(*cc, marker="+", color=INK2, ms=7, mew=0.9)
                ax.plot(*c, marker="o", color=VERMILION, ms=4)
                ax.annotate("", xy=c, xytext=cc,
                            arrowprops=dict(arrowstyle="->", color=VERMILION, lw=0.7))
            if k == 2:
                c = centroid(piece)
                m = second_moment(piece, c) / area(piece)
                w, v = np.linalg.eigh(m)
                ang = np.degrees(np.arctan2(v[1, 1], v[0, 1]))
                ax.add_patch(Ellipse(c, 2 * np.sqrt(w[1]), 2 * np.sqrt(w[0]), angle=ang,
                                     fill=False, ec=PURPLE, lw=1.0, ls="-"))
        ax.plot([a[0], b[0]], [a[1], b[1]], color=INK, lw=0.9, ls="--")
        ax.set_xlim(-0.15, 3.15)
        ax.set_ylim(-0.12, 1.25)
        ax.set_title(titles[k], fontsize=8)
        ax.text(1.5, -0.1, notes[k], ha="center", fontsize=6.5, va="top")
    fig.savefig(FIG / "diag-fill-moments.pdf")
    plt.close(fig)


# ------------------------------------------------------------------ c

def cube_faces() -> list[np.ndarray]:
    return [q for q in skin_bench.cube_quads(np.zeros((1, 3)), 1.0)]


def clip_cube(planes: list[tuple[np.ndarray, float]]) -> list[np.ndarray]:
    faces = cube_faces()
    for n, d in planes:
        n = n / np.linalg.norm(n)
        faces = skin_bench.clip(faces, n, d / 1.0, 1.0)
        if not faces:
            break
    return faces


def draw_piece(ax, faces: list[np.ndarray], color: str, alpha: float, lw: float = 0.5,
               ec: str = INK) -> None:
    ax.add_collection3d(Poly3DCollection(faces, fc=mpl.colors.to_rgba(color, alpha), ec=ec,
                                         lw=lw))


def fig_cuts() -> None:
    fig = plt.figure(figsize=(6.8, 3.0))
    u = lambda *v: np.array(v, float)  # noqa: E731
    cases = [
        ("corner cut: tetrahedron removed", [(u(1, 1, 1), 0.5)]),
        ("corner cut: tetrahedron kept", [(u(-1, -1, -1), -0.5)]),
        ("edge cut: a wedge (prism) kept", [(u(-1, -1, 0), -0.25)]),
        ("face-parallel cut: a slab", [(u(0, 0, 1), -0.2)]),
        ("oblique cut: hexagonal section", [(u(1, 1, 1), 0.0)]),
        ("two planes (a mesh edge): non-convex", None),
    ]
    for k, (title, planes) in enumerate(cases):
        ax = fig.add_subplot(2, 3, k + 1, projection="3d")
        ax.set_axis_off()
        ax.set_box_aspect((1, 1, 1))
        ax.view_init(elev=20, azim=-60)
        draw_piece(ax, cube_faces(), "white", 0.0, lw=0.4, ec=GHOST)
        if planes is not None:
            kept = clip_cube(planes)
            gone = clip_cube([(-n, -d) for n, d in planes])
        else:
            n1, n2 = u(1, 0, 0.8), u(-1, 0, 0.8)
            a1 = clip_cube([(n1, 0.1)])
            a2 = clip_cube([(-n1, -0.1), (n2, 0.1)])
            kept = a1 + a2
            gone = clip_cube([(-n1, -0.1), (-n2, -0.1)])
        if gone:
            draw_piece(ax, gone, GHOST, 0.12, lw=0.3, ec=GHOST)
        ax.add_collection3d(Poly3DCollection(kept, facecolors=shaded(kept, ORANGE),
                                             edgecolors=INK, linewidths=0.5))
        if k == 4:
            # label one face and one edge the way the closed form uses them
            f = max(kept, key=lambda q: np.dot(skin_bench_normal(q), u(1, 1, 1)))
            cen = f.mean(axis=0)
            nrm = skin_bench_normal(f)
            ax.quiver(*cen, *(0.45 * nrm), color=BLUE, lw=1.0, arrow_length_ratio=0.25)
            ax.text(*(cen + 0.5 * nrm), "$\\hat{\\mathbf{n}}_f$", color=BLUE, fontsize=8)
            i0 = max(range(len(f)), key=lambda i: np.linalg.norm(f[(i + 1) % len(f)] - f[i]))
            e0, e1 = f[i0], f[(i0 + 1) % len(f)]
            ax.plot(*np.array([e0, e1]).T, color=VERMILION, lw=2.0)
            ax.text(*(0.5 * (e0 + e1) + u(0, 0, -0.18)), "$e$", color=VERMILION, fontsize=8)
        r = 0.6
        ax.set_xlim(-r, r)
        ax.set_ylim(-r, r)
        ax.set_zlim(-r, r)
        ax.set_title(title, fontsize=7, pad=-4)
    fig.text(0.5, 0.01, "orange: the clipped piece (the part of the cell inside the body); "
             "grey: the part removed. Each piece is a polyhedron, so eq. (7) applies to it.",
             ha="center", fontsize=7)
    fig.savefig(FIG / "diag-cuts.pdf")
    plt.close(fig)


def skin_bench_normal(face: np.ndarray) -> np.ndarray:
    n = np.cross(face[1] - face[0], face[2] - face[0])
    return n / np.linalg.norm(n)


# ------------------------------------------------------------------ d

def fig_closed_form() -> None:
    fig = plt.figure(figsize=(6.8, 2.9))
    # (a) the face from the field point
    ax = fig.add_subplot(1, 2, 1, projection="3d")
    ax.set_axis_off()
    ax.view_init(elev=18, azim=-70)
    v = np.array([[0.0, 0.0, 1.0], [1.4, 0.2, 1.0], [0.5, 1.2, 1.0]])
    p = np.array([0.55, 0.35, 0.0])
    ax.add_collection3d(Poly3DCollection([v], fc=mpl.colors.to_rgba(SKY, 0.7), ec=BLUE, lw=1.0))
    for i, vi in enumerate(v):
        ax.plot(*np.array([p, vi]).T, color=INK2, lw=0.6, ls=":")
        ax.text(*(vi + [0.05, 0.0, 0.05]), f"$\\mathbf{{v}}_{i + 1}$", fontsize=8)
    foot = np.array([p[0], p[1], 1.0])
    ax.plot(*np.array([p, foot]).T, color=VERMILION, lw=1.2)
    ax.text(*(0.5 * (p + foot) + [0.08, 0, 0.12]), "$h_f$", color=VERMILION, fontsize=9)
    cen = v.mean(axis=0)
    ax.quiver(*cen, 0, 0, 0.45, color=BLUE, lw=1.0, arrow_length_ratio=0.25)
    ax.text(*(cen + [0.05, 0, 0.5]), "$\\hat{\\mathbf{n}}_f$", color=BLUE, fontsize=9)
    ax.scatter(*p, color=INK, s=12)
    ax.text(*(p + [0.05, 0, -0.12]), "field point $\\mathbf{p}$", fontsize=8)
    # the solid angle as the face projected on a small sphere about p
    t = np.linspace(0, 1, 30)
    for i in range(3):
        a_, b_ = v[i] - p, v[(i + 1) % 3] - p
        arc = np.array([(1 - s) * a_ + s * b_ for s in t])
        arc = 0.35 * arc / np.linalg.norm(arc, axis=1)[:, None] + p
        ax.plot(*arc.T, color=GREEN, lw=1.2)
    ax.text(*(p + [-0.45, 0.0, 0.3]), "$\\omega_f$", color=GREEN, fontsize=9)
    ax.set_xlim(0, 1.4)
    ax.set_ylim(0, 1.4)
    ax.set_zlim(0, 1.3)
    ax.set_title("(a) a face: height $h_f$ and solid angle $\\omega_f$", fontsize=8)
    # (b) the edge
    ax = fig.add_subplot(1, 2, 2)
    bare(ax)
    a, b = np.array([0.0, 0.0]), np.array([3.0, 0.0])
    q = np.array([1.1, 1.3])
    ax.plot(*np.array([a, b]).T, color=VERMILION, lw=2.2)
    ax.plot(*np.array([q, a]).T, color=INK2, lw=0.8)
    ax.plot(*np.array([q, b]).T, color=INK2, lw=0.8)
    ax.plot([q[0], q[0]], [q[1], 0], color=INK2, lw=0.6, ls=":")
    ax.scatter(*q, color=INK, s=12, zorder=3)
    ax.text(q[0] + 0.05, q[1] + 0.08, "$\\mathbf{p}$", fontsize=9)
    ax.text(0.35, 0.72, "$r_1$", fontsize=9)
    ax.text(2.15, 0.72, "$r_2$", fontsize=9)
    ax.text(1.5, -0.22, "edge $e$, length $L$", ha="center", color=VERMILION, fontsize=8)
    ax.text(q[0] + 0.05, 0.45, "$r_0$", fontsize=8, color=INK2)
    ax.text(1.5, -0.62, "$L_e = \\int_0^L dt/r = \\ln\\dfrac{r_1+r_2+L}{r_1+r_2-L}$", ha="center",
            fontsize=9)
    ax.text(1.5, -1.05, "near the edge: $r_1+r_2-L = \\dfrac{r_0^2}{r_1-\\ell_1}+\\dfrac{r_0^2}{r_2+\\ell_2}$",
            ha="center", fontsize=8)
    ax.set_xlim(-0.3, 3.3)
    ax.set_ylim(-1.3, 1.6)
    ax.set_title("(b) an edge: the logarithm $L_e$", fontsize=8)
    fig.savefig(FIG / "diag-closed-form.pdf")
    plt.close(fig)


# ------------------------------------------------------------------ e

def main() -> None:
    FIG.mkdir(exist_ok=True)
    style()
    fig_representations()
    fig_fill_moments()
    fig_cuts()
    fig_closed_form()


if __name__ == "__main__":
    main()
